import{_ as i,o as e,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2018-Apr-19 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-Apr-19 :: Ceph Performance Weekly","date":"2018-04-19T00:00:00.000Z","updated":"2018-04-20T00:00:00.000Z","tags":["Ceph性能","Blue Store Alligator","异步信使","统计信息收集","蓝鲸文件系统重构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Apr-19_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-Apr-19_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2018/2018-Apr-19_-_-_Ceph_Performance_Weekly.md"};function p(a,l,_,n,s,c){return e(),o("div",null,[...l[0]||(l[0]=[t("<p>会议纪要</p><p>会议时间：2018年4月19日</p><p>会议主题：性能会议</p><p>会议关键细节：</p><ol><li>Mimic版本处于冻结状态，ARS活动较少。</li><li>讨论了Blue Store Alligator策略的优化，Mike Market建议增加更多统计信息以更好地了解其工作情况。</li><li>讨论了收集分配器所需统计信息的方法，以了解其在生产环境中的工作方式和用途模式。</li><li>讨论了避免连续空间的需求，以及将BlueFS重构为与Sparks扩展兼容的方法。</li><li>讨论了异步信使的性能问题，特别是与CBT相关的 contention 和锁争用。</li></ol><p>讨论的主要议题：</p><ol><li><p>Blue Store Alligator策略的优化：</p><ul><li>收集更多统计信息，包括分配和释放的快照，以了解其在生产环境中的使用情况。</li><li>考虑重构BlueFS以避免连续空间的需求。</li></ul></li><li><p>异步信使的性能问题：</p><ul><li>优化异步信使的性能，特别是与CBT相关的 contention 和锁争用。</li><li>考虑禁用CBT以进行性能测试。</li></ul></li></ol><p>决定的事项：</p><ol><li>收集Blue Store Alligator的统计信息，包括分配和释放的快照。</li><li>考虑重构BlueFS以避免连续空间的需求。</li><li>优化异步信使的性能，特别是与CBT相关的 contention 和锁争用。</li></ol><p>后续行动计划：</p><ol><li>Mike Market将提交一个包含更多统计信息的TR。</li><li>评估重构BlueFS以避免连续空间的需求。</li><li>优化异步信使的性能，特别是与CBT相关的 contention 和锁争用。</li></ol><p>关键词：</p><ul><li>Ceph</li><li>Blue Store Alligator</li><li>统计信息</li><li>连续空间</li><li>异步信使</li><li>contention</li><li>锁争用</li><li>CBT</li><li>BlueFS</li><li>分布式存储</li><li>CRUSH算法</li><li>高可用性</li><li>扩展性</li><li>对象存储</li><li>块存储</li><li>文件系统存储</li><li>一致性</li><li>去中心化</li><li>性能</li><li>bluestore</li><li>bluefs</li><li>rocksdb</li><li>OSD</li><li>MON</li><li>MDS</li><li>PG</li><li>RADOS</li><li>librados</li><li>libcephfs</li><li>cephfs</li><li>rbd</li><li>radosgw</li><li>RGW</li><li>RESTful API</li><li>认证</li><li>授权</li><li>加密</li><li>损灭编码</li><li>复制</li><li>快照</li><li>克隆</li><li>虚拟化</li><li>云计算</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>混合云</li><li>多云</li><li>存储集群</li><li>节点</li><li>磁盘</li><li>SSD</li><li>HDD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>网络</li><li>拓扑</li><li>失败域</li><li>恢复</li><li>弹性</li><li>负载均衡</li><li>缓存</li><li>压缩</li><li>去重</li><li>分层</li><li>性能调优</li><li>基准测试</li><li>验证</li></ul>",13)])])}const d=i(r,[["render",p]]);export{S as __pageData,d as default};
